137:   // Pattern: "Passed Checks: 70" or "Passed: 20" or "Passed Checks:    127"
138:   const passMatch = stdout.match(/Passed Checks?:\s*([0-9]+)/i);
139:   const failMatch = stdout.match(/Failed Checks?:\s*([0-9]+)/i);
140: 
141:   if (passMatch) {
142:     passed = parseInt(passMatch[1], 10);
143:   }
144:   if (failMatch) {
145:     failed = parseInt(failMatch[1], 10);
146:   }
147: 
148:   // Count individual ✓ PASS occurrences if summary not found
149:   if (passed === 0) {
150:     const passTicks = (stdout.match(/✓\s*PASS|✔\s*PASS/g) || []).length;
151:     if (passTicks > 0) {
152:       passed = passTicks;
153:     }
154:   }
155: 
156:   // Fallback to minChecks if test reported clean pass
157:   if (passed === 0 && fallbackMin) {
158:     passed = fallbackMin;
159:   }
160: 
161:   return { passed, failed };
