const fs = require('fs');

function checkFeatureDistribution(file) {
  const code = fs.readFileSync(file, 'utf8');
  const matches = [...code.matchAll(/check\s*\(\s*['\"](F\d+)['\"]\s*,\s*['\"]([^'\"]+)['\"]/g)];
  const counts = {};
  matches.forEach(m => {
    const f = m[1];
    counts[f] = (counts[f] || 0) + 1;
  });
  console.log('Feature counts for', file, ':', counts);
  for (let i = 1; i <= 14; i++) {
    const fid = 'F' + i;
    if (!counts[fid] || counts[fid] < 5) {
      console.error(\`ERROR: \${fid} has \${counts[fid] || 0} checks (< 5) in \${file}\`);
      process.exit(1);
    }
  }
  console.log(\`All F1-F14 verified >= 5 checks each in \${file} (Total: \${matches.length})\`);
}

checkFeatureDistribution('tests/tier1_features/test-tier1-features.js');
